def construct_tree_from_string(s):
    index=0
    def parse():
        nonlocal index
        start=index
        if s[index]=='-':index+=1
        while index<len(s) and s[index].isdigit():index+=1
        node=TreeNode(int(s[start:index]))
        if index<len(s) and s[index]=='(':
            index+=1
            if s[index]!=')':node.left=parse()
            index+=1
        if index<len(s) and s[index]=='(':
            index+=1
            if s[index]!=')':node.right=parse()
            index+=1
        return node
    return parse()

